  /// Фраза для текущего момента. Меняется несколько раз в день, но в
  /// пределах одного слота стабильна — экран не «мигает» новой цитатой
  /// на каждой перерисовке.
  static WesiQuote current({DateTime? now}) {
    final t = now ?? DateTime.now();
    final dayNumber = DateTime(t.year, t.month, t.day)
        .difference(DateTime(2020, 1, 1))
        .inDays;
    final slot = (t.hour * slotsPerDay) ~/ 24;
    // Шаг взаимно прост с длиной списка, поэтому последовательность обходит
    // весь набор, а не вырождается в короткий цикл из нескольких фраз.
    final index = (dayNumber * slotsPerDay + slot) * _stride % all.length;
    return all[index];
  }

  /// Шаг обхода. Должен быть взаимно прост с [all].length — иначе
  /// последовательность зациклится на малом подмножестве.
  static final int _stride = _pickStride(all.length);

  static int _pickStride(int n) {
    // Берём первое число из списка кандидатов, взаимно простое с n.
    for (final candidate in [7, 11, 13, 17, 19, 23, 29, 31, 37]) {
      if (_gcd(candidate, n) == 1) return candidate;
    }
    return 1;
  }

  static int _gcd(int a, int b) => b == 0 ? a : _gcd(b, a % b);

  /// Случайная фраза — для кнопки «показать другую», когда пользователь
  /// сам захотел сменить, не дожидаясь следующего слота.
  static WesiQuote random([Random? rng]) =>
      all[(rng ?? Random()).nextInt(all.length)];
}
